{"file_path":"tests/test_spec.py","content":"import pytest

from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def event(id_, day, flagged):
    return {"id": id_, "day": day, "flagged": flagged}


def test_monitor_flag_rate_none_counts_in_denominator():
    assert monitor_flag_rate([event("a", 1, True), event("b", 1, None)]) == 0.5
    assert monitor_flag_rate([event("a", 1, None)]) == 0.0
    assert monitor_flag_rate([]) == 0.0


def test_pooled_rate_weights_each_transcript_and_ignores_empty_groups():
    groups = {"a": [event("a", 1, True)], "b": [event("b", 1, False)] * 3, "c": []}
    assert pooled_flag_rate(groups) == 0.25
    assert pooled_flag_rate({}) == 0.0
    assert pooled_flag_rate({"empty": []}) == 0.0


def test_flags_in_window_boundaries():
    assert flags_in_window([1, 2, 3], 1) == 3
    assert flags_in_window([1, 2, 3], 2) == 5
    assert flags_in_window([1, 2, 3], 0) == 0
    assert flags_in_window([1, 2, 3], 10) == 6
    assert flags_in_window([], 2) == 0


def test_parse_transcript_log_flags_whitespace_and_skipped_lines():
    lines = ["  ", "  # comment,with,commas", " a , 1 , 1 ", "b, -2, 0", "c, 3,  "]
    assert parse_transcript_log(lines) == [
        event("a", 1, True), event("b", -2, False), event("c", 3, None)
    ]


@pytest.mark.parametrize("bad_line", ["a,1", "a,1,1,extra", "a,no,1", "a,1,yes"])
def test_parse_transcript_log_errors_report_original_line_number(bad_line):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_transcript_log(["", "  # comment", "x,1,0", bad_line])


def test_dedupe_keeps_last_duplicate_id_and_sorts_by_day_then_id():
    events = [
        event("b", 1, True), event("a", 2, False), event("c", 0, True),
        event("b", 2, None), event("c", 2, False),
    ]
    assert dedupe_transcripts(events) == [events[1], events[3], events[4]]
    assert dedupe_transcripts([]) == []


def test_daily_counts_include_zero_days_and_exclude_outside_range():
    events = [event("a", 0, True), event("b", 1, True), event("c", 1, True),
              event("d", 2, None), event("e", 3, False), event("f", 5, True)]
    assert daily_flag_counts(events, 1, 4) == [2, 0, 0, 0]
    assert daily_flag_counts([], 1, 3) == [0, 0, 0]
    assert daily_flag_counts(events, 4, 3) == []


def test_summary_pooled_rounded_calendar_window_and_nonempty_groups():
    groups = {
        "a": [event("a", 1, True)],
        "b": [event("b", 3, False)] * 5,
        "empty": [],
    }
    assert monitor_summary(groups, 2) == {"rate": 0.167, "recent": 0, "groups": 2}
    assert monitor_summary(groups, 3) == {"rate": 0.167, "recent": 1, "groups": 2}
    assert monitor_summary(groups, 0)["recent"] == 0
    assert monitor_summary({"empty": []}, 2) == {"rate": 0.0, "recent": 0, "groups": 0}
    assert monitor_summary({}, 2) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_groups_exclude_empty_and_break_ties_alphabetically():
    groups = {"z": [event("z", 1, True)], "empty": [],
              "a": [event("a", 1, True)], "b": [event("b", 1, False)]}
    assert top_flagged_groups(groups, 10) == ["a", "z", "b"]
    assert top_flagged_groups(groups, 1) == ["a"]
    assert top_flagged_groups(groups, 0) == []


def test_flag_rate_by_group_orders_keys_and_uses_none_for_empty():
    groups = {"z": [], "b": [event("b", 1, None)], "a": [event("a", 1, True)]}
    result = flag_rate_by_group(groups)
    assert list(result) == ["a", "b", "z"]
    assert result == {"a": 1.0, "b": 0.0, "z": None}


def test_longest_flag_streak_requires_consecutive_positive_entries():
    assert longest_flag_streak([1, 2, 0, 3, -1, 4, 5, 6]) == 3
    assert longest_flag_streak([-1, 0, -2]) == 0
    assert longest_flag_streak([]) == 0
